int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    int pos = 0;
    std::stack<int> depth_stack;
    std::stack<int> item_stack;

    depth_stack.push(0);
    item_stack.push(0);

    while (start < end && pos < item_limit) {
        if (depth_stack.top() >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos)
                *error_pos = pos;
            return 1;
        }

        switch (*start) {
            case 'd': {
                lazy_entry dict;
                if (!dict.init_dict()) {
                    ec = error_code::memory_allocation_failed;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                depth_stack.push(depth_stack.top() + 1);
                item_stack.push(0);
                start++;
                break;
            }
            case 'l': {
                lazy_entry list;
                if (!list.init_list()) {
                    ec = error_code::memory_allocation_failed;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                depth_stack.push(depth_stack.top() + 1);
                item_stack.push(0);
                start++;
                break;
            }
            case 'i': {
                // Parse integer
                if (start + 1 >= end) {
                    ec = error_code::unexpected_end_of_input;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                int end_pos;
                char* endptr;
                long long value = std::strtoll(start + 1, &endptr, 10);
                if (endptr == start + 1 || endptr == end) {
                    ec = error_code::invalid_integer_format;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                lazy_entry int_entry;
                int_entry.init_int(value);
                ret.add_child(int_entry);
                start = endptr;
                pos++;
                item_stack.top()++;
                break;
            }
            case 'e': {
                if (depth_stack.size() <= 1) {
                    ec = error_code::invalid_end_of_structure;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                depth_stack.pop();
                item_stack.pop();
                start++;
                break;
            }
            case '0' ... '9': {
                // Parse string
                long long len = 0;
                char* endptr;
                len = std::strtoll(start, &endptr, 10);
                if (endptr == start || *endptr != ':') {
                    ec = error_code::invalid_string_format;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                if (start + (endptr - start + 1 + len) > end) {
                    ec = error_code::unexpected_end_of_input;
                    if (error_pos)
                        *error_pos = pos;
                    return 1;
                }
                lazy_entry str;
                str.init_str(static_cast<int>(len), start + (endptr - start + 1));
                ret.add_child(str);
                start = start + (endptr - start + 1 + len);
                pos++;
                item_stack.top()++;
                break;
            }
            default: {
                ec = error_code::unexpected_token;
                if (error_pos)
                    *error_pos = pos;
                return 1;
            }
        }
    }

    if (start != end) {
        ec = error_code::unexpected_end_of_input;
        if (error_pos)
            *error_pos = pos;
        return 1;
    }

    if (depth_stack.top() != 0) {
        ec = error_code::unterminated_structure;
        if (error_pos)
            *error_pos = pos;
        return 1;
    }

    return 0;
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    std::stack<int> item_stack;

    depth_stack.push(0);
    item_stack.push(0);

    char const* pos = start;

    while (pos < end && depth_stack.top() < depth_limit && item_stack.top() < item_limit) {
        if (*pos == 'd') {
            // Dictionary start
            if (!lazy_entry::is_dict(ret)) {
                ec.assign(lazy_entry::invalid_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            if (!ret.dict().empty()) {
                ec.assign(lazy_entry::unexpected_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            depth_stack.push(depth_stack.top() + 1);
            item_stack.push(0);

            ++pos;
        }
        else if (*pos == 'l') {
            // List start
            if (!lazy_entry::is_list(ret)) {
                ec.assign(lazy_entry::invalid_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            if (!ret.list().empty()) {
                ec.assign(lazy_entry::unexpected_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            depth_stack.push(depth_stack.top() + 1);
            item_stack.push(0);

            ++pos;
        }
        else if (*pos == 'i') {
            // Integer
            ++pos;
            char const* num_start = pos;
            while (pos < end && *pos >= '0' && *pos <= '9') ++pos;

            if (pos == num_start || pos == end || *pos != 'e') {
                ec.assign(lazy_entry::invalid_integer, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            if (!lazy_entry::is_int(ret)) {
                ec.assign(lazy_entry::unexpected_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            std::string num_str(num_start, pos - num_start);
            long long value;
            try {
                value = std::stoll(num_str);
            } catch (...) {
                ec.assign(lazy_entry::invalid_integer, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            ret.integer(value);

            ++item_stack.top();
            ++pos;
        }
        else if (*pos == 'e') {
            // End of structure
            if (depth_stack.top() == 0) {
                ec.assign(lazy_entry::unexpected_end, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            depth_stack.pop();
            item_stack.pop();

            ++pos;
        }
        else if (*pos >= '0' && *pos <= '9') {
            // String
            char const* num_start = pos;
            while (pos < end && *pos >= '0' && *pos <= '9') ++pos;

            if (pos == num_start || pos == end || *pos != ':') {
                ec.assign(lazy_entry::invalid_string, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            std::string num_str(num_start, pos - num_start);
            int length;
            try {
                length = std::stoi(num_str);
            } catch (...) {
                ec.assign(lazy_entry::invalid_string, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            if (length < 0 || pos + length > end) {
                ec.assign(lazy_entry::unexpected_end, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            if (!lazy_entry::is_string(ret)) {
                ec.assign(lazy_entry::unexpected_type, std::generic_category());
                if (error_pos) *error_pos = pos - start;
                return 1;
            }

            ret.string(std::string(pos + 1, length));

            ++item_stack.top();
            pos += length + 1;
        }
        else {
            // Unknown character
            ec.assign(lazy_entry::invalid_data, std::generic_category());
            if (error_pos) *error_pos = pos - start;
            return 1;
        }
    }

    if (depth_stack.top() != 0 || item_stack.top() != 0) {
        ec.assign(lazy_entry::unexpected_end, std::generic_category());
        if (error_pos) *error_pos = end - start;
        return 1;
    }

    return 0;
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> stack;
    int depth = 0;
    const char* current = start;

    while (current < end && depth < depth_limit) {
        if (item_limit <= 0) {
            ec = make_error_code(errc::too_many_items);
            if (error_pos)
                *error_pos = static_cast<int>(current - start);
            return static_cast<int>(ec);
        }

        --item_limit;

        switch (*current) {
            case 'd': // Dictionary
                ++depth;
                stack.push(depth);
                // Add dictionary logic
                ++current;
                break;
            case 'l': // List
                ++depth;
                stack.push(depth);
                // Add list logic
                ++current;
                break;
            case 'i': // Integer
                // Parse integer
                ++current;
                const char* int_end = std::find_if(current, end, [](char c) { return c == 'e'; });
                if (int_end == end) {
                    ec = make_error_code(errc::unexpected_end_of_data);
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                try {
                    int64_t value = std::stoll(std::string(current, int_end));
                    ret = lazy_entry{value};
                } catch (...) {
                    ec = make_error_code(errc::invalid_integer);
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                current = int_end + 1;
                break;
            case 'e': // End of structure
                if (stack.empty()) {
                    ec = make_error_code(errc::unbalanced_structure);
                    if (error_pos)
                        *error_pos = static_cast<int>(current - start);
                    return static_cast<int>(ec);
                }

                stack.pop();
                --depth;
                ++current;
                break;
            case ':': // String
                {
                    // Parse string length
                    const char* len_start = current;
                    const char* len_end = std::find(len_start, end, ':');
                    if (len_end == end) {
                        ec = make_error_code(errc::invalid_string_format);
                        if (error_pos)
                            *error_pos = static_cast<int>(current - start);
                        return static_cast<int>(ec);
                    }

                    int len = 0;
                    try {
                        len = std::stoi(std::string(len_start, len_end));
                    } catch (...) {
                        ec = make_error_code(errc::invalid_string_format);
                        if (error_pos)
                            *error_pos = static_cast<int>(current - start);
                        return static_cast<int>(ec);
                    }

                    if (len_start == len_end || len < 0) {
                        ec = make_error_code(errc::invalid_string_format);
                        if (error_pos)
                            *error_pos = static_cast<int>(current - start);
                        return static_cast<int>(ec);
                    }

                    if (len + (len_end - start) > static_cast<int>(end - start)) {
                        ec = make_error_code(errc::unexpected_end_of_data);
                        if (error_pos)
                            *error_pos = static_cast<int>(current - start);
                        return static_cast<int>(ec);
                    }

                    std::string str(len_end + 1, len);
                    ret = lazy_entry{str};
                    current = len_end + 1 + len;
                    break;
                }
            default:
                ec = make_error_code(errc::unknown_token);
                if (error_pos)
                    *error_pos = static_cast<int>(current - start);
                return static_cast<int>(ec);
        }
    }

    if (depth > 0) {
        ec = make_error_code(errc::unbalanced_structure);
        if (error_pos)
            *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec);
    }

    if (current != end) {
        ec = make_error_code(errc::extra_data);
        if (error_pos)
            *error_pos = static_cast<int>(current - start);
        return static_cast<int>(ec);
    }

    ec = error_code();
    return 0;
}

int decode_lazy_entry(char const* start, char const* end, lazy_entry& ret, error_code& ec, int* error_pos, int depth_limit, int item_limit) {
    std::stack<int> depth_stack;
    int current_depth = 0;
    const char* current = start;
    int items_parsed = 0;

    while (current < end && items_parsed < item_limit) {
        // Check and increment depth
        if (current_depth >= depth_limit) {
            ec = error_code::depth_limit_exceeded;
            if (error_pos) *error_pos = current - start;
            return static_cast<int>(ec);
        }

        depth_stack.push(current_depth);
        ++current_depth;

        // Process the type of lazy entry
        switch (*current) {
            case 'd':
                // Dictionary entry
                ret = lazy_entry();
                ret.type = lazy_entry::dict_type;
                ++current;
                break;
            case 'l':
                // List entry
                ret = lazy_entry();
                ret.type = lazy_entry::list_type;
                ++current;
                break;
            case 'i':
                // Integer entry
                ++current;
                if (current >= end) {
                    ec = error_code::unexpected_end;
                    if (error_pos) *error_pos = current - start;
                    return static_cast<int>(ec);
                }

                // Parse integer value
                // (Implementation of parsing integer omitted for brevity)
                ret = lazy_entry();
                ret.type = lazy_entry::int_type;
                ++current;
                break;
            case '4':
                // String entry
                if (current + 1 >= end) {
                    ec = error_code::unexpected_end;
                    if (error_pos) *error_pos = current - start;
                    return static_cast<int>(ec);
                }

                // Parse string length and value
                // (Implementation of parsing string omitted for brevity)
                ret = lazy_entry();
                ret.type = lazy_entry::string_type;
                current += 2;
                break;
            default:
                ec = error_code::invalid_entry_type;
                if (error_pos) *error_pos = current - start;
                return static_cast<int>(ec);
        }

        ++items_parsed;

        if (current >= end) {
            ec = error_code::unexpected_end;
            if (error_pos) *error_pos = current - start;
            return static_cast<int>(ec);
        }

        // Pop depth
        if (!depth_stack.empty()) {
            depth_stack.pop();
            --current_depth;
        }
    }

    ec = error_code::success;
    return 0;
}

